LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE v_id uuid; v_old_hash bytea;
BEGIN
 IF p_account_id IS NULL OR p_event_id IS NULL OR length(p_event_id)<1
  OR p_event_type IS NULL OR p_object_id IS NULL OR p_payload_hash IS NULL
  THEN RAISE EXCEPTION 'BILLING_WEBHOOK_INPUT_INCOMPLETE' USING ERRCODE='P0001'; END IF;
