  WHERE provider_account_id=p_account_id AND event_id=p_event_id;
 IF FOUND THEN
  IF v_old_hash<>p_payload_hash
   THEN RAISE EXCEPTION 'BILLING_WEBHOOK_HASH_QUARANTINE' USING ERRCODE='P0001'; END IF;
  RETURN v_id;
 END IF;
 v_id := gen_random_uuid();
 INSERT INTO billing_webhook_inbox(id,provider_account_id,event_id,event_type,object_id,provider_created_at,payload_encrypted,payload_hash,state,attempts)
  VALUES(v_id,p_account_id,p_event_id,p_event_type,p_object_id,p_provider_created_at,p_payload_encrypted,p_payload_hash,'received',0);
 RETURN v_id;
