CREATE FUNCTION photo.billing_claim_webhook(p_worker_id uuid,p_batch_size bigint) RETURNS TABLE(inbox_id uuid,fence uuid)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE v_fence uuid; rec record;
BEGIN
 IF p_batch_size IS NULL OR p_batch_size<1 OR p_batch_size>100
  THEN RAISE EXCEPTION 'BILLING_CLAIM_BATCH_INVALID' USING ERRCODE='P0001'; END IF;
 FOR rec IN
  SELECT id FROM billing_webhook_inbox
   WHERE state IN ('received','retry')
     AND (lease_until IS NULL OR lease_until<clock_timestamp())
   ORDER BY created_at
   LIMIT p_batch_size
   FOR UPDATE SKIP LOCKED
 LOOP
  v_fence := gen_random_uuid();
  UPDATE billing_webhook_inbox
   SET state='processing', attempts=attempts+1, processing_token=v_fence,
       lease_until=clock_timestamp()+INTERVAL'5 minutes'
   WHERE id=rec.id;
  inbox_id := rec.id; fence := v_fence;
  RETURN NEXT;
 END LOOP;
END $$;
