CREATE FUNCTION photo.billing_apply_provider_snapshot(p_inbox_id uuid,p_fence uuid,p_snapshot jsonb) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE w billing_webhook_inbox%ROWTYPE; v_result text;
BEGIN
 SELECT * INTO w FROM billing_webhook_inbox WHERE id=p_inbox_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_INBOX_NOT_FOUND' USING ERRCODE='P0001'; END IF;
 IF w.processing_token IS DISTINCT FROM p_fence
  THEN RAISE EXCEPTION 'BILLING_FENCE_STALE' USING ERRCODE='P0001'; END IF;
 IF w.state='applied' THEN RETURN 'applied'; END IF;
 IF w.state NOT IN ('processing') THEN
  UPDATE billing_webhook_inbox SET state='retry',next_retry_at=clock_timestamp()+INTERVAL'30 seconds'
   WHERE id=p_inbox_id;
  RETURN 'retry';
 END IF;
 INSERT INTO billing_outbox(id,topic,business_key,payload,state)
  VALUES(gen_random_uuid(),'billing.webhook.apply',p_inbox_id::text,p_snapshot,'pending')
  ON CONFLICT (topic,business_key) DO NOTHING;
 UPDATE billing_webhook_inbox SET state='applied' WHERE id=p_inbox_id;
 v_result := 'applied';
 RETURN v_result;
END $$;
